	TOWER_ARCANE_WIZARD_4_DISINTEGRATE_1_DESCRIPTION = "Phóng tia phép tiêu diệt ngay mục tiêu. Với trùm và trùm phụ, tia phép gây %$towers.arcane_wizard.disintegrate.boss_damage[1]%$ sát thương phép.",
