	ENEMY_ASH_SPIRIT_DESCRIPTION = "Nó trở thành một tinh thần khủng khiếp, mạnh mẽ, sinh ra từ đá, nấm mốc và buồn nôn.",
	TAUNT_STAGE18_ERIDAN_FIGHT_0003 = "IDEU ĐÂY ĐÂY!",
	LEVEL_37_HISTORY = "Đã qua cửa truyền, chúng ta bước vào đất nước của đám mây. Nhiệm vụ của chuyến đi này đã rõ ràng: giúp Ollion bảo vệ \"người thợ mỏ cuối cùng\". Vì thế, chúng ta phải đi đến một lâu đài của người bảo vệ, một lâu đỉnh cổ đại, một lâu đời nhỏ, nhưng đã trải qua cuộc chiến của người bảo hộ.\nĐột nhiên, một tiếng động mạnh mẽ lên phía trước, chúng tôi phải nhanh chóng bước đi cứu hộ.",
