	LEVEL_38_HISTORY = "Sau trận chiến khó khăn nhất, chúng tôi cuối cùng đã lấy lại lâu đài của người bảo vệ, và bây giờ chúng tôi có thể vào \"cơ đài thánh\" - nơi là nơi thánh của \"thương tử\" Lunales, chịu trách nhiệm bảo vệ nơi này của Nữ hoàng Thương tử. Đã có thời gian, nhưng mong mọi thứ vẫn còn.",
	BOSS_SPIDER_QUEEN_EXTRA = "- Làm choáng tháp\n- Hút máu quân địch gần đó\n- Triệu hồi nhện hút máu\n- Ném mạng nhện che tầm nhìn của bạn",
	LEVEL_31_HISTORY = "Sau chiến tranh, vương quốc trở lại hòa bình. Giờ đây, chỉ cần lắng nghe sóng bắn biển, đặt một vòng tròn, chờ đợi một người bạn cũ. Tuy nhiên, ngay cả khi có một cái gió yên tĩnh, tôi chỉ sợ ngày bình yên này không nhiều.",
