	HERO_SPIDER_SUPREME_HUNTER_DESCRIPTION_2 = "Spydyr chớp mắt dịch chuyển đến kẻ địch có nhiều máu nhất, gây %$heroes.hero_spider.supreme_hunter.damage_min[2]%$ - %$heroes.hero_spider.supreme_hunter.damage_max[2]%$ sát thương.",
	HERO_LAVA_HOTHEADED_DESCRIPTION_2 = "Khi Khartoe hồi sinh, sát thương của tháp phòng thủ gần đó tăng lên %$heroes.hero_lava.hotheaded.s_damage_factors[2]%$ %, kéo dài %$heroes.hero_lava.hotheaded.durations[2]%$ giây.",
	ITEM_ROOM_EQUIPPED = "Đã trang bị",
	LEVEL_26_HISTORY = "Tôi đi qua một cái núi lớn và đi qua một căn phòng đầy những chiếc xe lớn, những thứ trong xe này không thể nào. Không có gì ngạc nhiên khi những người lười biếng này đầy sức mạnh, kỹ năng và hình dạng cũng như một mô-đun được vẽ ra. Tất cả đều là những người lười biếng - những người lừa đảo! Ông sử dụng các nguồn khoa học ác để tạo ra các bản sao của mình. - Thưa ông, chúng ta phải ngăn chặn mọi chuyện!",
